import React from "react"

type ImageItem = {
  id: string
  src?: string
  alt?: string
}

type Props = {
  images: ImageItem[] // provide up to 9
}

export default function ImageGrid({ images }: Props) {
  // ensure we always render 9 tiles (like your 3x3 layout)
  const tiles = Array.from({ length: 9 }).map((_, i) => images[i] ?? { id: `empty-${i}` })

  return (
    <section className="w-[922px] h-[982px] flex flex-col items-center justify-center py-[30px]">
      <div className="w-[922px] h-[922px]">
        <div className="grid grid-cols-3 gap-[15px] w-full h-full">
          {tiles.map((img, idx) => (
            <div
              key={img.id ?? `tile-${idx}`}
              className="
                relative
                w-[297.33px] h-[297.33px]
                rounded-[15px]
                overflow-hidden
                bg-[rgba(165,165,165,0.068)]
                shadow-[2px_4px_25px_rgba(165,165,165,0.10),_inset_2.14645px_2.00046px_9.24px_rgba(165,165,165,0.126),_inset_1.21725px_1.13446px_4.62px_rgba(165,165,165,0.126)]
              "
            >
              {img.src ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={img.src}
                  alt={img.alt ?? "Portfolio image"}
                  className="absolute inset-0 w-full h-full object-cover"
                />
              ) : null}

              {/* (optional) overlay / sliders / description can be added later */}
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}
